package com.pocketcode

/** Готовый навык или команда: ставится одним нажатием. */
data class CatalogItem(val isSkill: Boolean, val name: String, val title: String, val about: String, val content: String)

private fun skill(name: String, title: String, desc: String, body: String) =
    CatalogItem(true, name, title, desc, "---\nname: $name\ndescription: $desc\n---\n\n$body\n")

private fun cmd(name: String, title: String, desc: String, body: String) =
    CatalogItem(false, name, title, desc, "---\ndescription: $desc\n---\n\n$body\n")

